const CACHE='zvit-v6';const ASSETS=['./','./index.html','./style.css','./app.js','./calc.mjs','./contacts.mjs','./travel-template.mjs','./a5-front.png','./a5-back.png','./manifest.webmanifest','./icon.svg','./icon-192.png','./icon-512.png'];
self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS)).then(()=>self.skipWaiting())));
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('zvit-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==location.origin)return;const path=new URL(e.request.url).pathname;if(!ASSETS.some(a=>new URL(a,self.location).pathname===path))return;e.respondWith(fetch(e.request).then(r=>{if(r.ok&&!r.redirected&&r.type!=='opaqueredirect'){const copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy))}return r}).catch(()=>caches.match(e.request).then(r=>r||caches.match('./index.html'))))});
